<template><aside class="editor-panel widget-library" aria-label="Widget library"><header><p class="overlay-kicker">Widgets</p><h2>Widget Library</h2><input v-model="search" type="search" placeholder="Search widgets" aria-label="Search widgets"></header><section v-for="group in groups" :key="group.category"><h3>{{ group.category }}</h3><button v-for="item in group.items" :key="item.type" type="button" @click="$emit('add',item.type)"><span>{{ item.icon }}</span><span><b>{{ item.displayName }}</b><small>Demo widget</small></span><i>+</i></button></section><section class="planned-providers"><h3>Planned providers</h3><p>Discord · YouTube · More Respawn data</p></section></aside></template>
<script setup>import { computed,ref } from 'vue'; import { widgetDefinitions } from '../../overlays/widgetRegistry.js'; defineEmits(['add']); const search=ref(''); const groups=computed(()=>{const map=new Map(); for(const item of widgetDefinitions.filter(i=>i.displayName.toLowerCase().includes(search.value.toLowerCase()))){const list=map.get(item.category)||[];list.push(item);map.set(item.category,list)}return [...map].map(([category,items])=>({category,items}))})</script>
